import{_ as t,c as i,o as a,a3 as r}from"./chunks/framework.CoV49S2T.js";const p=JSON.parse(`{"title":"Guide d'utilisation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/usage.md","filePath":"fr/guide/usage.md","lastUpdated":1787284674000}`),o={name:"fr/guide/usage.md"};function s(l,e,n,u,c,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="guide-d-utilisation" tabindex="-1">Guide d&#39;utilisation <a class="header-anchor" href="#guide-d-utilisation" aria-label="Permalink to &quot;Guide d&#39;utilisation&quot;">​</a></h1><h2 id="historique-du-presse-papiers" tabindex="-1">Historique du presse-papiers <a class="header-anchor" href="#historique-du-presse-papiers" aria-label="Permalink to &quot;Historique du presse-papiers&quot;">​</a></h2><p>ClipboxAI s&#39;exécute depuis votre <strong>barre de menus</strong>. À chaque fois que vous copiez quelque chose, il est ajouté à votre historique.</p><ul><li>Cliquez sur l&#39;icône de la barre de menus pour ouvrir le panneau d&#39;historique.</li><li>Survolez un élément et appuyez sur le raccourci de l&#39;action, ou cliquez pour le recopier dans le presse-papiers.</li><li>Utilisez le champ de recherche pour trouver un élément par son texte.</li></ul><h2 id="la-fenetre-outil-ia" tabindex="-1">La fenêtre Outil IA <a class="header-anchor" href="#la-fenetre-outil-ia" aria-label="Permalink to &quot;La fenêtre Outil IA&quot;">​</a></h2><p>La fenêtre <strong>Outil IA</strong> est l&#39;endroit où s&#39;exécutent les actions. Elle utilise une disposition en deux volets :</p><ul><li><strong>Gauche</strong> — une liste d&#39;outils, regroupés en : <ul><li><strong>IA intégrée</strong> — résumé, traduction et autres actions IA.</li><li><strong>Local intégré</strong> — outils hors ligne (extraire les liens, compter les statistiques, réduire les lignes vides).</li><li><strong>Installés</strong> — actions que vous avez ajoutées depuis le Marketplace. Vous pouvez glisser pour les <strong>réorganiser</strong>.</li></ul></li><li><strong>Droite</strong> — deux panneaux : l&#39;élément <strong>original</strong> d&#39;un côté et le <strong>résultat</strong> de l&#39;autre.</li></ul><p>Les outils IA affichent un badge « cloud » ; les outils locaux affichent un badge « appareil », ainsi vous savez toujours si une action utilise le réseau.</p><h2 id="executer-une-action" tabindex="-1">Exécuter une action <a class="header-anchor" href="#executer-une-action" aria-label="Permalink to &quot;Exécuter une action&quot;">​</a></h2><ol><li>Sélectionnez un outil dans la liste de gauche (ou acceptez une suggestion intelligente).</li><li>L&#39;élément en cours apparaît dans le panneau <strong>original</strong>.</li><li>Le résultat est produit dans le panneau <strong>résultat</strong>.</li></ol><h3 id="execution-automatique" tabindex="-1">Exécution automatique <a class="header-anchor" href="#execution-automatique" aria-label="Permalink to &quot;Exécution automatique&quot;">​</a></h3><p>Activez <strong>Exécuter automatiquement à la sortie</strong> dans le pied de la fenêtre. Lorsqu&#39;elle est activée, l&#39;outil sélectionné s&#39;exécute automatiquement dès que vous copiez quelque chose — aucun clic manuel n&#39;est nécessaire. Les outils locaux n&#39;écrasent jamais votre presse-papiers, l&#39;exécution automatique est donc sûre.</p><h2 id="outils-locaux-integres" tabindex="-1">Outils locaux intégrés <a class="header-anchor" href="#outils-locaux-integres" aria-label="Permalink to &quot;Outils locaux intégrés&quot;">​</a></h2><p>Ceux-ci s&#39;exécutent entièrement hors ligne sur votre Mac :</p><ul><li><strong>Extraire les liens</strong> — renvoie toutes les URL trouvées dans le texte.</li><li><strong>Compter les statistiques</strong> — nombre de mots / caractères / lignes / phrases.</li><li><strong>Réduire les lignes vides</strong> — supprime les lignes vides du texte collé.</li></ul><h2 id="configuration-de-l-ia-cloud" tabindex="-1">Configuration de l&#39;IA cloud <a class="header-anchor" href="#configuration-de-l-ia-cloud" aria-label="Permalink to &quot;Configuration de l&#39;IA cloud&quot;">​</a></h2><p>Pour utiliser les actions IA, connectez un fournisseur dans <strong>Réglages → IA</strong> :</p><ol><li>Choisissez un fournisseur — <strong>DeepSeek</strong>, <strong>MiniMax</strong>, <strong>Zhipu GLM</strong>, <strong>Kimi (Moonshot)</strong>, <strong>Mistral</strong>, <strong>Ollama</strong> (local), ou un autre service compatible OpenAI.</li><li>Collez votre <strong>clé API</strong>. Elle est stockée dans le <strong>Keychain</strong>, jamais écrite en texte clair sur le disque.</li><li>Choisissez un modèle.</li><li>L&#39;IA cloud est désactivée par défaut. Lorsqu&#39;elle est activée, votre élément n&#39;est envoyé qu&#39;au fournisseur que vous avez configuré.</li></ol><p>Si aucune clé n&#39;est définie, la bannière de configuration vous le rappelle dans la fenêtre Outil IA.</p><h2 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h2><ol><li>Ouvrez le <strong>Marketplace</strong> depuis la fenêtre Outil IA (ou la page <a href="/fr/marketplace/">Marketplace</a> du site).</li><li>Cliquez sur <strong>Installer</strong> sur une action. Cela ouvre l&#39;application via le lien profond <code>clipboxai://install?action=&lt;id&gt;</code> et ajoute l&#39;action à votre liste <strong>Installés</strong>.</li></ol><h2 id="raccourcis-clavier" tabindex="-1">Raccourcis clavier <a class="header-anchor" href="#raccourcis-clavier" aria-label="Permalink to &quot;Raccourcis clavier&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Raccourci</th><th>Action</th></tr></thead><tbody><tr><td><code>Cmd+Shift+V</code></td><td>Ouvrir l&#39;historique du presse-papiers</td></tr><tr><td><code>Cmd+,</code></td><td>Ouvrir les réglages</td></tr><tr><td><code>Cmd+W</code></td><td>Fermer la fenêtre</td></tr><tr><td><code>Cmd+Q</code></td><td>Quitter l&#39;application</td></tr></tbody></table><blockquote><p>Les raccourcis exacts peuvent varier selon les versions ; consultez <strong>Réglages → Raccourcis</strong> dans l&#39;application.</p></blockquote><h2 id="reglages" tabindex="-1">Réglages <a class="header-anchor" href="#reglages" aria-label="Permalink to &quot;Réglages&quot;">​</a></h2><p>Ouvrez <strong>ClipboxAI → Réglages</strong> (ou <code>Cmd+,</code>) :</p><ul><li><strong>Général</strong> : langue, lancement à la connexion, thème d&#39;apparence.</li><li><strong>IA</strong> : fournisseur cloud, modèle et clé API (Keychain).</li><li><strong>Actions</strong> : bascule d&#39;exécution automatique, applications exclues et ordre des outils.</li><li><strong>Confidentialité</strong> : option d&#39;IA cloud, applications exclues et contrôles de l&#39;historique.</li><li><strong>Marketplace</strong> : parcourir et gérer les actions installées.</li></ul>',27)])])}const h=t(o,[["render",s]]);export{p as __pageData,h as default};
